#include <stdio.h>
#include <string.h>
int main() {
    char texte[100] = "bonjour mon amie";
    strcat(texte, " ");
    char mot[100] = "";
    char resultat[200] = "";
    char c[2];
    int i;
    for (i = 0; i < strlen(texte); i++) {
        c[0] = texte[i];
        c[1] = '\0';
        if (c[0] != ' ') {
            strcat(mot, c);
        } else {
            if (strlen(mot) > 2 && strcmp(mot, "mon") != 0) {
                char temp[200];
                strcpy(temp, mot);
                strcat(temp, resultat);
                strcpy(resultat, temp);
            }
            strcpy(mot, "");
        }
    }
    printf("Résultat : %s\n", resultat);
    return 0;
}

